// Escalamiento (manual del asesor o obligatorio por política). En producción: Teams/correo al supervisor.
const e = $json.body;
const obligatorio = e.origen === 'politica';
return [{ json: {
  escalamiento_id: e.escalamiento_id,
  canal: obligatorio ? 'Teams #supervision-urgente + correo al supervisor de turno' : 'Teams #supervision',
  sla_minutos: 10, // Política de Escalamiento: el supervisor responde en máximo 10 minutos
  mensaje: `${obligatorio ? 'Escalamiento obligatorio' : 'Escalamiento manual'} · cliente ${e.cliente_id ?? 'sin identificar'}`
         + ` · ${e.motivo} · asesor ${e.asesor}`,
} }];
